query:
mutation sitesCreateWifiRadioProfile ( $accountId:ID! $createWifiRadioProfileInput:CreateWifiRadioProfileInput!) {
	sites ( accountId:$accountId ) {
		createWifiRadioProfile ( input:$createWifiRadioProfileInput  )  {
			wifiRadioProfile {
				id
				site {
					id
					name
				}
				band24 {
					band
					standard
					channelWidth
					dfsEnabled
					channel
				}
				band5 {
					band
					standard
					channelWidth
					dfsEnabled
					channel
				}
			}
		}
	}	
}
